  use Veltrion\Services\AI\FeatureEngine\DTOs\FeatureDTO; class ImpactAnalyzer { private string $projectRoot; public function __construct(?string $projectRoot = null) { $this->projectRoot = $projectRoot ?? __DIR__ . '/../../../../'; } public function analyzeImpact(FeatureDTO $feature): array { $slug = $feature->slug; $cleanName = strtolower(str_replace('-', '', $slug)); $affectedModules = ['App\\UseCases', 'App\\Domain', 'App\\Adapters']; $affectedFiles = []; $affectedRoutes = ['/api/' . $slug]; $databaseChanged = false; $requiredAgents = ['qa', 'security', 'architecture', 'docs']; if (str_contains(strtolower($feature->description), 'base de datos') || str_contains(strtolower($feature->description), 'crud') || str_contains(strtolower($feature->description), 'sql')) { $databaseChanged = true; $requiredAgents[] = 'database'; $requiredAgents[] = 'performance'; } if (str_contains(strtolower($feature->description), 'web') || str_contains(strtolower($feature->description), 'ui') || str_contains(strtolower($feature->description), 'frontend')) { $requiredAgents[] = 'ux'; $requiredAgents[] = 'e2e'; } $impactData = [ 'feature_id' => $feature->id, 'feature_name' => $feature->name, 'affected_modules' => $affectedModules, 'affected_routes' => $affectedRoutes, 'database_changed' => $databaseChanged, 'potential_regressions' => [ "Verificar compatibilidad de firmas de interfaces en UseCases", "Comprobar integridad de referencias en SQLite" ], 'required_agents' => array_unique($requiredAgents) ]; $this->saveImpactReport($impactData); return $impactData; } private function saveImpactReport(array $impactData): void { $dir = $this->projectRoot . '/storage/reports/impact'; if (!is_dir($dir)) { mkdir($dir, 0777, true); } $jsonFile = $dir . "/{$impactData['feature_id']}_impact.json"; file_put_contents($jsonFile, json_encode($impactData, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)); } } 